using System.Text;using LWS.TruckSports;using LWS.TruckFareFight;using LWS.TruckBowling;using LWS.TruckFieldGoal;using UnityEngine;using UnityEngine.InputSystem;
namespace LWS.TruckTeaParty {
 public sealed class TeaMatch:SportsEventSession,IServingEvents {
  public ServingArm[] arms;public ServingVessel[] pots;public TeaCup[] cups;public TeaGuest[] guests;public SportsDrivingViews drivingViews;public SportsEventCamera broadcast;public FieldGoalCrowd crowd;public Transform[] spillPuddles;public TeaRules rules=new TeaRules();public Key[] pourKeys={Key.Q,Key.PageUp,Key.Y,Key.O},bowKeys={Key.E,Key.PageDown,Key.B,Key.P};public int ActualServings{get;private set;}public int ActualPours{get;private set;}public int ActualBreaks{get;private set;}
  readonly bool[] extrasReleased=new bool[4];readonly FareFightRoute[] routes=new FareFightRoute[4];readonly int[] state=new int[4],currentCup=new int[4],currentPot=new int[4],lastCup={-1,-1,-1,-1};readonly float[] gesture=new float[4],embarrassedUntil=new float[4];readonly Vector3[] withdrawGoal=new Vector3[4];int puddleCursor;readonly StringBuilder standings=new StringBuilder(300);
  public override string Title=>"TRUCK TEA PARTY";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override int WeatherCount=>1;public override bool SupportsSplitAIViews=>true;public override bool CompactBroadcastStatus=>true;public override bool CompactViewportHud=>true;public override int CompactScoreColumns=>4;public override bool MultiViewHUD=>drivingViews!=null&&!drivingViews.NeedsArena;
  public override string OptionLabel=>option==0?"AFTERNOON TEA · 3 MIN":option==1?"GARDEN PARTY · 4 MIN":"LEISURELY SERVICE · 5 MIN";public override string Header=>Title+" · "+(rules.Clock<3?"READY "+Mathf.CeilToInt(3-rules.Clock):Mathf.CeilToInt(rules.Remaining)+"s");public override string Status=>rules.Clock<3?"GUESTS ARE SETTLING IN":rules.Complete?"":ActualServings+" CUPS SERVED · "+ActualBreaks+" BROKEN DISHES";
  public override string Help=>"Host an elegant garden tea with a real articulated serving arm on your original NWH truck. Drive and steer use configured controls. ACTION grabs a nearby physical vessel touching the wrist sensor; a fresh ACTION press releases it. Hold ACTION and steer/accelerate to rotate the arm sideways/raise it while the truck handbrake holds. Pour: keyboard Q/PageUp/Y/O for drivers1–4, whole/half controller own right/left shoulder (whole RB). Bow: keyboard E/PageDown/B/P, whole West, own half stick-click. These extra keys are validated against every active keyboard driver's controls. Pour physically from the teapot spout into a hollow cup; the actual ballistic stream must cross its opening. Fill near85%; below75% is insufficient. Tea spills from missed streams, overflow or tipped cups. Dishes break on strong native impacts. Return/release the teapot, pick up a filled cup, drive gently to its marked guest and set it on the real table. An upright intact cup resting there for0.6seconds scores precision/intact/minimal-spill points once. Wrong guests cannot score. A nearby visible arm bow after serving adds15 courtesy points once. Animated guests react to actual service. AI uses the same vessels, arm, stream, table contacts and gestures. Three cups per guest are finite; a broken cup is lost, never replaced during play. Source pots contain finite tea. In-place serving tools do not teleport truck or cargo. Shared/chase/cab, profiles, pause/help/input recovery/results/rematch use the existing flow.";
  public override bool TryReadScoreCard(int slot,out string score,out string detail){bool valid=slot>=0&&slot<setup.count;score=valid?rules.points[slot]+" PTS":"";detail=valid?rules.served[slot]+" SERVED · "+rules.bows[slot]+" BOWS":"";return valid;}
  public override bool TryReadViewportCard(int view,out int participant,out string score,out string detail)=>TryReadDrivingViewportCard(drivingViews,view,out participant,out score,out detail);public override string ViewportTelemetry(int view)=>Readout(drivingViews.rally.owners[view]);public override string ViewText(int view){int s=drivingViews.rally.owners[view];return setup.players[s].name+" · "+rules.points[s]+" PTS\n"+Readout(s);}public string Readout(int slot){var v=arms[slot].Held;return v!=null?(v.pourable?"TEAPOT ":"CUP ")+v.Volume.ToString("F2")+" / "+v.capacity.ToString("F1"):lastCup[slot]>=0&&guests[cups[lastCup[slot]].guestId].Visiting(slot)?"COURTESY BOW":"READY TO SERVE";}
  public override string Standings{get{standings.Clear();for(int p=1;p<=setup.count;p++)for(int i=0;i<setup.count;i++)if(rules.Place(i)==p)standings.Append('#').Append(p).Append(' ').Append(setup.players[i].name).Append(" · ").Append(rules.points[i]).Append(" PTS · ").Append(rules.served[i]).Append(" CUPS · ").Append(rules.spilled[i].ToString("F2")).Append(" SPILLED\n");return standings.ToString();}}public override string Results=>"AFTERNOON TEA COMPLETE\n\n"+Standings;
  public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;for(int i=0;i<setup.count;i++){if(setup.players[i].source!=BowlingSource.Keyboard)continue;foreach(var k in new[]{pourKeys[i],bowKeys[i]}){if(k==Key.None||k==Key.Escape||pourKeys[i]==bowKeys[i]){reason="Assign distinct tea pouring/bow keys; Escape remains pause.";return false;}for(int j=0;j<setup.count;j++){var p=setup.players[j];if(p.source!=BowlingSource.Keyboard)continue;if(k==p.forward||k==p.back||k==p.left||k==p.right||k==actionKeys[j]||j!=i&&(k==pourKeys[j]||k==bowKeys[j])){reason="Tea key conflicts with keyboard driver "+(j+1);return false;}}}}return true;}
  protected override void BeginGame(){if(arms.Length!=4||pots.Length!=8||cups.Length!=12||guests.Length!=4)throw new System.InvalidOperationException("Author the complete garden service.");rules.Reset(setup.count,option);ActualServings=ActualPours=ActualBreaks=0;puddleCursor=0;foreach(var puddle in spillPuddles)puddle.gameObject.SetActive(false);for(int i=0;i<4;i++){extrasReleased[i]=false;withdrawGoal[i]=Vector3.zero;state[i]=currentCup[i]=0;currentPot[i]=i*2;lastCup[i]=-1;gesture[i]=0;routes[i]??=new FareFightRoute();routes[i].Reset();arms[i].gameObject.SetActive(i<setup.count);if(i<setup.count)arms[i].Prepare(new Vector3((i-1.5f)*30,.65f,-48),Quaternion.identity);guests[i].ResetGuest();}foreach(var pot in pots)pot.Prepare();foreach(var cup in cups){cup.vessel.Prepare();cup.vessel.gameObject.SetActive(cup.guestId<setup.count);}Physics.SyncTransforms();drivingViews.Layout();crowd?.ResetAttempt();}
  protected override void Simulate(float dt){rules.Tick(dt);if(rules.Complete){for(int i=0;i<setup.count;i++)if(rules.Place(i)==1)ConfirmOutcome("tea-champion:"+i,i,rules.points[i],"ELEGANT HOST","PTS",SportsScoreTier.MatchChampion,matchEnded:true);EndMatch();return;}foreach(var pot in pots){pot.InteractionEnabled=rules.Active;pot.TickLiquid(dt);}foreach(var cup in cups)if(cup.guestId<setup.count){cup.vessel.InteractionEnabled=rules.Active;cup.vessel.TickLiquid(dt);}ActualPours=0;foreach(var pot in pots)ActualPours+=pot.NativePours;if(!rules.Active){for(int i=0;i<setup.count;i++)Hold(arms[i].truck);return;}
   for(int i=0;i<setup.count;i++){arms[i].clock=rules.Clock;bool ai=setup.players[i].source==BowlingSource.AI;if(ai)Bot(i,dt);else{bool pour=ExtraHeld(i,true),bow=ExtraHeld(i,false),adjust=ActionHeld(i);if(actions[i]){if(arms[i].Held!=null)arms[i].Drop();else arms[i].Grab();}if(adjust)Hold(arms[i].truck);else arms[i].truck.TickDrive(commands[i]);arms[i].Manual(commands[i],adjust,pour,dt);if(bow)Bow(i,dt);else gesture[i]=0;}if(rules.Clock<embarrassedUntil[i]&&arms[i].Held==null)arms[i].Move(arms[i].grip.position+arms[i].truck.transform.right*Mathf.Sin(rules.Clock*12)*.08f,0,false,dt);}
  }
  bool ExtraHeld(int slot,bool pour){var p=setup.players[slot];if(!Ready(slot)||!p.released){extrasReleased[slot]=false;return false;}bool raw(bool usePour){if(p.source==BowlingSource.Keyboard)return SportsDeviceInput.KeyHeld(usePour?pourKeys[slot]:bowKeys[slot]);if(!p.Controller)return false;if(p.source==BowlingSource.WholeController)return usePour?p.pad.rightShoulder.isPressed:p.pad.buttonWest.isPressed;bool right=p.source==BowlingSource.RightStick;return usePour?(right?p.pad.rightShoulder:p.pad.leftShoulder).isPressed:(right?p.pad.rightStickButton:p.pad.leftStickButton).isPressed;}if(!extrasReleased[slot]){if(raw(true)||raw(false))return false;extrasReleased[slot]=true;}return raw(pour);}
  static void Hold(SportsEventTruck t){t.TickDrive(Vector2.zero);var input=t.tractorMotor.vehicle.input;input.states.handbrake=input.states.handbrakeRaw=1;}
  bool Approach(int slot,Vector3 point,float dt){var t=arms[slot].truck;float distance=Vector3.ProjectOnPlane(point-t.body.position,Vector3.up).magnitude;if(distance<2){Hold(t);return t.body.linearVelocity.magnitude<.6f;}routes[slot].DirectGoal(t.body.position,point);var drive=routes[slot].Drive(t.body,t.transform,(int)setup.players[slot].difficulty,dt,1);drive.y=Mathf.Clamp(drive.y,-.4f,.6f);t.TickDrive(drive);return false;}
  void Bot(int slot,float dt){var arm=arms[slot];int id=slot*3+currentCup[slot];while(currentCup[slot]<3&&(cups[id].vessel.Broken||state[slot]==0&&rules.CupDone(id))){currentCup[slot]++;id=slot*3+currentCup[slot];state[slot]=0;}if(currentCup[slot]>=3){Hold(arm.truck);arm.Move(arm.truck.transform.TransformPoint(new Vector3(0,2.5f,7)),0,false,dt);return;}var cup=cups[id];var pot=pots[currentPot[slot]];var source=Source(slot);var guest=guests[cup.guestId];bool ready;
   switch(state[slot]){
    case 0:if(arm.Held!=null&&arm.Held!=pot)arm.Drop();ready=Approach(slot,source,dt);arm.Move(pot.body.position,0,false,dt);if(pot.Broken||pot.Volume<.15f){currentPot[slot]=slot*2+1;pot=pots[currentPot[slot]];if(pot.Broken||pot.Volume<.15f){state[slot]=8;break;}}if(ready&&arm.Grab())state[slot]=1;break;
    case 1:Hold(arm.truck);if(arm.Held!=pot){state[slot]=0;break;}var desired=cup.vessel.transform.position+Vector3.up*2.4f-Vector3.forward*.25f;arm.Move(desired-(pot.spout.position-arm.grip.position),62,false,dt);if(cup.vessel.Volume>=.85f)state[slot]=2;break;
    case 2:Hold(arm.truck);arm.Move(pot.spawn+Vector3.up*.2f-(pot.body.position-arm.grip.position),0,false,dt);if(Vector3.Distance(pot.body.position,pot.spawn+Vector3.up*.2f)<.45f&&pot.body.linearVelocity.magnitude<.7f){arm.Drop();state[slot]=3;}break;
    case 3:Hold(arm.truck);arm.Move(cup.vessel.body.position,0,false,dt);if(arm.Grab()){if(arm.Held==cup.vessel)state[slot]=9;else arm.Drop();}break;
    case 9:Hold(arm.truck);var carry=arm.truck.transform.TransformPoint(new Vector3(0,4.5f,6));AimHeld(arm,carry,dt);if(AtCup(cup,carry))state[slot]=4;break;
    case 4:ready=Approach(slot,guest.transform.position-Vector3.forward*8,dt);AimHeld(arm,arm.truck.transform.TransformPoint(new Vector3(0,4.5f,6)),dt);if(ready)state[slot]=5;break;
    case 5:Hold(arm.truck);var above=ServicePlacement(cup)+Vector3.up*1.3f;AimHeld(arm,above,dt);if(AtCup(cup,above))state[slot]=10;break;
    case 10:Hold(arm.truck);var placement=ServicePlacement(cup);AimHeld(arm,placement,dt);if(AtCup(cup,placement)){var away=Vector3.ProjectOnPlane(arm.grip.position-cup.vessel.body.position,Vector3.up).normalized;if(away.sqrMagnitude<.5f)away=-arm.truck.transform.forward;withdrawGoal[slot]=arm.grip.position+away*1.2f;arm.Drop();state[slot]=11;}break;
    case 11:Hold(arm.truck);arm.Move(withdrawGoal[slot],0,false,dt);if(Vector3.Distance(arm.grip.position,withdrawGoal[slot])<.1f)state[slot]=6;break;
    case 6:Hold(arm.truck);arm.Move(withdrawGoal[slot]+Vector3.up*2.5f,0,false,dt);if(cup.vessel.Banked)state[slot]=7;else if(cup.vessel.Broken){currentCup[slot]++;state[slot]=0;}break;
    case 7:Hold(arm.truck);Bow(slot,dt);if(gesture[slot]<=0){currentCup[slot]++;state[slot]=0;}break;
    default:Hold(arm.truck);break;
   }
  }
  // Three distinct near-side locations are inside this guest's actual physical
  // tabletop. Carry above it, align there, then lower; never drag a low cup into its edge.
  public Vector3 ServicePlacement(TeaCup cup){var table=guests[cup.guestId].table.bounds;float margin=1.6f;return new Vector3(Mathf.Clamp(table.center.x+(cup.cupId%3-1)*3,table.min.x+margin,table.max.x-margin),table.max.y+.2f,table.min.z+margin);}
  static void AimHeld(ServingArm arm,Vector3 bodyTarget,float dt){if(arm.Held!=null)arm.Move(bodyTarget-(arm.Held.body.position-arm.grip.position),0,false,dt);}
  static bool AtCup(TeaCup cup,Vector3 target)=>Vector3.Distance(cup.vessel.body.position,target)<.4f&&cup.vessel.body.linearVelocity.magnitude<.7f;
  public static Vector3 Source(int slot)=>new Vector3((slot-1.5f)*30,0,-36);
  void Bow(int slot,float dt){if(arms[slot].Held!=null||lastCup[slot]<0)return;var guest=guests[cups[lastCup[slot]].guestId];if(!guest.Visiting(slot)||arms[slot].truck.body.linearVelocity.magnitude>.5f)return;gesture[slot]+=dt;float pitch=Mathf.Sin(Mathf.Clamp01(gesture[slot]/1.5f)*Mathf.PI)*28;arms[slot].Move(arms[slot].truck.transform.TransformPoint(new Vector3(0,2.5f,6)),pitch,false,dt);if(gesture[slot]>=1.5f){int delta=rules.Courtesy(slot,lastCup[slot],true,arms[slot].Tilt<8);if(delta>0)ConfirmScore("courtesy:"+lastCup[slot],slot,delta,rules.points[slot],"POLITE BOW",SportsScoreTier.Small);gesture[slot]=0;}}
  public bool Serve(TeaCup cup,TeaGuest guest){var v=cup.vessel;int slot=v.LastCarrier;if(slot<0||slot>=setup.count||v.Holder!=null||v.Broken||v.Banked||v.LastSupport!=guest.table||v.SupportAge>.1f)return false;int delta=rules.Serve(slot,cup.cupId,guest.id,cup.guestId,v.Volume,v.SpilledVolume,true,true);if(delta<=0)return false;v.MarkBanked();lastCup[slot]=cup.cupId;ActualServings++;ConfirmScore("served-cup:"+cup.cupId,slot,delta,rules.points[slot],"PRECISE TEA SERVICE",SportsScoreTier.Major);feedback.PlayAt(3,v.body.position,0,true);if(guest.attendant!=null)guest.attendant.CrossFade("Cheer",.2f);crowd?.React(true,"TEA SERVED",v.body.position);return true;}
  public void Spilled(ServingVessel source,float amount,Vector3 point){rules.Spill(source.LastCarrier,amount);if(spillPuddles==null||spillPuddles.Length==0)return;var puddle=spillPuddles[puddleCursor++%spillPuddles.Length];puddle.gameObject.SetActive(true);puddle.position=new Vector3(point.x,.025f,point.z);puddle.localScale=new Vector3(Mathf.Sqrt(amount)*3+ .2f,.01f,Mathf.Sqrt(amount)*3+.2f);}
  public void DishBroken(ServingVessel source,Vector3 point){ActualBreaks++;var cup=source.GetComponentInChildren<TeaCup>();rules.Broken(source.LastCarrier,cup!=null?cup.cupId:-1);if(source.LastCarrier>=0)embarrassedUntil[source.LastCarrier]=rules.Clock+2;feedback.PlayAt(4,point,0,true);crowd?.React(false,"BROKEN PORCELAIN",point);}
  public override void DescribeBroadcast(SportsBroadcastAction action,SportsBroadcastFraming framing){int slot=framing.Nearest(Vector3.zero,true);if(slot<0)slot=0;action.primary=slot;var held=arms[slot].Held;var point=held!=null?held.body.position:arms[slot].grip.position;action.Objective(point,2);action.reason=held!=null?"ACTUAL VESSEL / PHYSICAL POUR":"SERVING ARM / GUEST";}
  protected override void Present(float dt){if(!Running)return;drivingViews.Tick(dt);if(drivingViews.NeedsArena&&broadcast.LegacyPoseAllowed)broadcast.Pose(arms[0].truck.body.position,new Vector3(0,25,-34),60);}
  public override void ExtraAction(string key){if(key=="drivingview")drivingViews.Cycle();}protected override void StopSounds(){if(arms!=null)foreach(var arm in arms)if(arm!=null)arm.truck.StopSound();}protected override void StopGame(){if(arms!=null)foreach(var arm in arms)if(arm!=null)arm.Freeze();if(pots!=null)foreach(var pot in pots)if(pot!=null)pot.Freeze();if(cups!=null)foreach(var cup in cups)if(cup!=null)cup.vessel.Freeze();StopSounds();}
 }
}
